<template>
  <div class="vr-gallery-container" :class="themeId" v-if="sceneItems.length">
    <div class="vr-gallery-box">
      <div class="vr-gallery-card" :class="hide ? 'hide' : ''">
        <div class="vr-gallery-list">
          <div
            v-for="(item, index) in sceneItems"
            :key="index"
            class="vr-item"
            @click="handleSceneChange(item)"
            :class="
              (!nowScene && index === 0) || (nowScene && item.id === nowScene.id)
                ? 'active'
                : ''
            "
          >
            <div
              class="vr-item-cover"
              :style="{ backgroundImage: `url(${item.thumbUrl})` }"
            >
              <div class="text-ellipsis vr-item-title" :title="item.title">
                <span
                  class="txt"
                  :class="item.title.length > 10 ? 'moving' : ''"
                  >{{ item.title }}</span
                >
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
    
    <script>
import { getProductScenes } from '@/api/vr'
export default {
  name: 'VRGallery',
  data() {
    return {
      themeId: 'theme-default',
      nowScene: null,
      sceneItems: [],
    }
  },
  props: {
    hide: {
      type: Boolean,
      default: false,
    },
    id: {
      type: String,
      default: null,
    },
  },
  mounted() {
    this.getSceneList()
  },
  computed: {},
  methods: {
    async getSceneList() {
      this.sceneItems = await getProductScenes(this.id)
      // console.log('this.sceneItems:', this.sceneItems)
      this.$emit('onSceneListLoaded', this.sceneItems.length > 0 ? this.sceneItems[0] : null)
    },
    handleSceneChange(scene) {
      this.nowScene = scene
      this.$emit('onSceneChange', scene)
    }
  },
}
</script>
